export class OrderComponent {
  id = input.required<number>();
  // zamiast ngOnChanges:
  title = computed(() => `Zamówienie #${this.id()}`);
  // zamiast ngAfterViewInit:
  chart = viewChild<ElementRef>('chart');
  constructor() {
    afterNextRender(() => initChart(this.chart()!.nativeElement));
    inject(DestroyRef).onDestroy(() => disposeChart());
  }
}

